/*
 * A simple music player for Game Boy.
 *
 * Port of presets/nes/music.c, which drives two pulse channels and a
 * triangle (bass) channel from a compact note stream. The Game Boy has
 * two pulse channels and a wave channel, so the triangle maps to the
 * wave channel and the same score plays on two pulses + wave.
 *
 * Score format (identical to the NES version):
 *   byte < 0x80   a note number (index into the period tables below)
 *   byte >= 0x80  end of chord; low 6 bits = duration in frames
 *   0xff          end of score
 *
 * Notes < BASS_NOTE go to the wave channel, the rest to the pulses,
 * exactly like the NES player routes low notes to the triangle.
 */

//#link "gb/sfr.sgb"
//#link "gb/crt0.sgb"
//#resource "gb/global.sgb"
#include <stdint.h>
#include <string.h>
#include "gb/types.h"
#include "gb/hardware.h"
#include "gb/gb.h"
#include "gbtext.h"

typedef uint8_t byte;
typedef uint16_t word;

#define BASS_NOTE 36

/* Note indices match the NES score: MIDI note = index + 20.
 * Pulse periods are 11-bit: f = 131072 / (2048 - X). Indices below 16
 * are under the pulse channel's range and clamp to X = 0. */
const word note_table_pulse[64] = {
  0x000,0x000,0x000,0x000,0x000,0x000,0x000,0x000,
  0x000,0x000,0x000,0x000,0x000,0x000,0x000,0x000,
  0x02c,0x09d,0x107,0x16b,0x1c9,0x223,0x277,0x2c7,
  0x312,0x358,0x39b,0x3da,0x416,0x44e,0x483,0x4b5,
  0x4e5,0x511,0x53b,0x563,0x589,0x5ac,0x5ce,0x5ed,
  0x60b,0x627,0x642,0x65b,0x672,0x689,0x69e,0x6b2,
  0x6c4,0x6d6,0x6e7,0x6f7,0x706,0x714,0x721,0x72d,
  0x739,0x744,0x74f,0x759,0x762,0x76b,0x773,0x77b,
};

/* Wave-channel periods: f = 65536 / (2048 - X). The wave channel goes
 * an octave lower than the pulses, so it covers the low bass notes. */
const word note_table_wave[64] = {
  0x000,0x000,0x000,0x000,0x02c,0x09d,0x107,0x16b,
  0x1c9,0x223,0x277,0x2c7,0x312,0x358,0x39b,0x3da,
  0x416,0x44e,0x483,0x4b5,0x4e5,0x511,0x53b,0x563,
  0x589,0x5ac,0x5ce,0x5ed,0x60b,0x627,0x642,0x65b,
  0x672,0x689,0x69e,0x6b2,0x6c4,0x6d6,0x6e7,0x6f7,
  0x706,0x714,0x721,0x72d,0x739,0x744,0x74f,0x759,
  0x762,0x76b,0x773,0x77b,0x783,0x78a,0x790,0x797,
  0x79d,0x7a2,0x7a7,0x7ac,0x7b1,0x7b6,0x7ba,0x7be,
};

/* 32-sample bass waveform, two 4-bit samples per byte. */
const uint8_t wave_pattern[16] = {
  0x01,0x23,0x45,0x67,0x89,0xab,0xcd,0xa8,0x88,0x44,0x88,0x98,0x76,0x54,0x32,0x10
};

/* 8x8 music note sprite (2bpp: low plane, high plane per row).
 * Colour index 1 (low plane only), so index 0 stays transparent. */
const uint8_t note_tile[16] = {
  0x1e,0x00, 0x1c,0x00, 0x10,0x00, 0x10,0x00,
  0x10,0x00, 0x78,0x00, 0xf8,0x00, 0x70,0x00
};

byte default_pulse_duty = 0x20;
byte default_pulse_vol = 8;

extern const byte music1[];       /* score -- see end of file */

byte cur_duration = 0;
byte chs = 0;              /* channels assigned for the current chord */

const byte* music_ptr = 0;
const byte* music_rts = 0;
byte music_runlen = 0;

// decode next music byte, handling compression
byte next_music_byte(void) {
  byte ch = *music_ptr++;
  if (music_runlen) {
    // we are in a backreference, count down
    if (--music_runlen == 0) {
      music_ptr = music_rts;
    }
  } else if (ch == 0xfe) {
    // back-reference: 0xfe <offset> <length>
    byte offset = *music_ptr++;
    music_runlen = *music_ptr++;
    music_rts = music_ptr;
    music_ptr -= offset + 3;
    return next_music_byte();
  }
  return ch;
}

void psg_init(void) {
  byte i;
  NR52_REG = 0x80;         /* sound on */
  NR51_REG = 0xFF;         /* all channels to both outputs */
  NR50_REG = 0x77;         /* master volume */
  NR10_REG = 0x00;         /* pulse 1 sweep off */
  /* load wave RAM with the wave DAC off */
  NR30_REG = 0x00;
  for (i = 0; i < 16; i++) _AUD3WAVERAM[i] = wave_pattern[i];
  NR32_REG = 0x20;         /* wave output level 100% */
}

void gb_pulse_note(byte ch, word period, byte vol) {
  byte lo = (byte)(period & 0xff);
  byte hi = (byte)((period >> 8) & 0x07);
  byte env = (byte)((vol << 4) | 0x02);  /* decay envelope from vol */
  if (ch == 0) {
    NR11_REG = default_pulse_duty;
    NR12_REG = env;
    NR13_REG = lo;
    NR14_REG = (byte)(0x80 | hi);  /* trigger */
  } else {
    NR21_REG = default_pulse_duty;
    NR22_REG = env;
    NR23_REG = lo;
    NR24_REG = (byte)(0x80 | hi);  /* trigger */
  }
}

void gb_wave_note(word period) {
  NR30_REG = 0x80;         /* wave DAC on */
  NR31_REG = 0x00;         /* length (unused) */
  NR32_REG = 0x20;         /* 100% volume */
  NR33_REG = (byte)(period & 0xff);
  NR34_REG = (byte)(0x80 | ((period >> 8) & 0x07));  /* trigger */
}

void play_music(void) {
  if (music_ptr) {
    /* run out the duration timer, fetching notes as needed */
    while (cur_duration == 0) {
      byte note = next_music_byte();
      if ((note & 0x80) == 0) {
        /* pulses play higher notes, wave handles the low bass */
        if (note >= BASS_NOTE || (chs & 4)) {
          word period = note_table_pulse[note & 63];
          /* use whichever pulse generator is free */
          if (!(chs & 1)) {
            gb_pulse_note(0, period, default_pulse_vol);
            chs |= 1;
          } else if (!(chs & 2)) {
            gb_pulse_note(1, period, default_pulse_vol);
            chs |= 2;
          }
        } else {
          gb_wave_note(note_table_wave[note & 63]);
          chs |= 4;
        }
      } else {
        /* end of chord: set duration and free every channel */
        if (note == 0xff) music_ptr = 0;
        cur_duration = note & 63;
        chs = 0;
      }
    }
    cur_duration--;
  }
}

void start_music(const byte* music) {
  music_ptr = music;
  cur_duration = 0;
  chs = 0;
}

void main(void) {
  /* title screen (LCD off while writing tiles and the tile map) */
  DISPLAY_OFF;
  BGP_REG = 0xE4;
  OBP0_REG = OBP1_REG = 0xE4;
  font_init();
  put_str(0, 7, "Ty zh mene pidmanula");
  put_str(0, 9, "(Pidmanula, Pidvela)");
  /* one music note tile, shown by two sprites */
  set_sprite_data(0, 1, note_tile);
  set_sprite_tile(0, 0);
  set_sprite_tile(1, 0);
  SHOW_BKG;
  SHOW_SPRITES;
  DISPLAY_ON;

  psg_init();
  music_ptr = 0;
  while (1) {
    if (!music_ptr) start_music(music1);
    wait_vbl_done();
    play_music();
    /* sprite X follows the low byte of each music pointer (folded on screen) */
    move_sprite(0, (uint8_t)(((uint8_t)music_ptr & 0x7f) + 16), 120);
    move_sprite(1, (uint8_t)(((uint8_t)music_rts & 0x7f) + 16), 130);
  }
}

